def get_wallpaper(wallpaper_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_mon = time.perf_counter()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- request log (received) ----
    requests = _load("requests.json")
    req_id = "req_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "api_key_id": None,
        "tool_name": "get_wallpaper",
        "status": "received",
        "started_at": now_iso,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {"wallpaper_id": wallpaper_id},
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    requests.append(req_row)
    _save("requests.json", requests)

    def _finalize_ok(body, http_status=200, **updates):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "fulfilled"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["updated_at"] = end_iso
                for k, v in updates.items():
                    r[k] = v
                break
        _save("requests.json", requests)
        return body

    def _finalize_fail(code, msg, http_status, err_code=None):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "failed"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["error_code"] = err_code or code
                r["error_message"] = msg
                r["updated_at"] = end_iso
                break
        _save("requests.json", requests)
        return _err(code, msg, http_status=http_status)

    # ---- validate input ----
    if wallpaper_id is None or not isinstance(wallpaper_id, str):
        return _finalize_fail("VALIDATION_ERROR", "wallpaper_id must be a string", 400, err_code="INVALID_WALLPAPER_ID_TYPE")
    if not re.fullmatch(r"^[0-9a-z]{6}$", wallpaper_id):
        return _finalize_fail("VALIDATION_ERROR", "wallpaper_id must match ^[0-9a-z]{6}$", 400, err_code="INVALID_WALLPAPER_ID_FORMAT")

    # ---- ambient auth resolution + rate limits/quota ----
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _finalize_fail("UNAUTHORIZED", "No active API key available for this request", 401, err_code="NO_ACTIVE_KEY")

    # choose a key that is under rate/quota right now
    # daily quota: use requests_today and reset time if day rolled
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    one_min_ago = now - datetime.timedelta(minutes=1)

    # pre-index requests in last minute by api_key_id
    last_min_counts = {}
    for r in requests:
        ak = r.get("api_key_id")
        if not ak:
            continue
        st = _parse_dt(r.get("started_at"))
        if st and st >= one_min_ago:
            last_min_counts[ak] = last_min_counts.get(ak, 0) + 1

    chosen = None
    quota_blocked = False
    rate_blocked = False
    for k in active_keys:
        kid = k.get("id")
        if not kid:
            continue

        # reset requests_today if reset_at not same UTC date
        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None:
            reset_at = now
        if reset_at.date() != now.date():
            k["requests_today"] = 0
            k["requests_today_reset_at"] = now_iso
            k["updated_at"] = now_iso

        daily_quota = k.get("daily_quota")
        rate_limit = k.get("rate_limit_per_minute")
        if not isinstance(daily_quota, int) or daily_quota < 1:
            continue
        if not isinstance(rate_limit, int) or rate_limit < 1:
            continue

        if int(k.get("requests_today") or 0) >= daily_quota:
            quota_blocked = True
            continue

        if last_min_counts.get(kid, 0) >= rate_limit:
            rate_blocked = True
            continue

        chosen = k
        break

    if chosen is None:
        # persist any resets we may have applied
        _save("api_keys.json", api_keys)
        if quota_blocked:
            return _finalize_fail("QUOTA_EXCEEDED", "Daily quota exceeded", 429, err_code="DAILY_QUOTA_EXCEEDED")
        if rate_blocked:
            return _finalize_fail("RATE_LIMIT", "Rate limit exceeded", 429, err_code="RATE_LIMIT_EXCEEDED")
        return _finalize_fail("UNAUTHORIZED", "No eligible API key available", 401, err_code="NO_ELIGIBLE_KEY")

    # attach key to request log row
    for r in requests:
        if r.get("id") == req_id:
            r["api_key_id"] = chosen["id"]
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    # enforce quota/rate by recording this request attempt counts: requests.json is the source of truth for rate;
    # daily quota counter is maintained in api_keys.requests_today (increment only on fulfilled/failed? vendor says requests).
    # We'll increment for any authenticated call that is processed (this one), regardless of cache hit.
    chosen["requests_today"] = int(chosen.get("requests_today") or 0) + 1
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # ---- serve from cache (no upstream available offline) ----
    wallpapers = _load("wallpapers.json")
    wp = None
    for row in wallpapers:
        if isinstance(row, dict) and row.get("id") == wallpaper_id:
            wp = row
            break

    if wp is None:
        # offline service cannot fetch upstream; treat as not found
        return _finalize_fail("NOT_FOUND", "Wallpaper not found", 404, err_code="WALLPAPER_NOT_FOUND")

    # If cached but not active, treat accordingly
    if wp.get("status") in ("deleted", "blocked"):
        return _finalize_fail("NOT_FOUND", "Wallpaper not available", 404, err_code="WALLPAPER_UNAVAILABLE")

    # Mark request as cache hit
    for r in requests:
        if r.get("id") == req_id:
            r["upstream_cache_hit"] = True
            r["result_wallpaper_id"] = wallpaper_id
            r["result_count"] = 1
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    payload = wp.get("raw_payload")
    if payload is None:
        payload = {}

    return _finalize_ok(
        {"data": payload},
        http_status=200,
        result_wallpaper_id=wallpaper_id,
        result_count=1,
        upstream_cache_hit=True,
    )

def search_wallpapers(query=None, categories=None, purity=None, sorting=None, order=None, top_range=None, atleast=None, resolutions=None, ratios=None, colors=None, page=None, seed=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # defaults
    if sorting is None:
        sorting = "date_added"
    if order is None:
        order = "desc"
    if page is None:
        page = 1

    # ---- request log (received) ----
    requests = _load("requests.json")
    req_id = "req_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "api_key_id": None,
        "tool_name": "search_wallpapers",
        "status": "received",
        "started_at": now_iso,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {
            "query": query, "categories": categories, "purity": purity, "sorting": sorting, "order": order,
            "top_range": top_range, "atleast": atleast, "resolutions": resolutions, "ratios": ratios,
            "colors": colors, "page": page, "seed": seed
        },
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    requests.append(req_row)
    _save("requests.json", requests)

    def _finalize_ok(body, http_status=200, **updates):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "fulfilled"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["updated_at"] = end_iso
                for k, v in updates.items():
                    r[k] = v
                break
        _save("requests.json", requests)
        return body

    def _finalize_fail(code, msg, http_status, err_code=None):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "failed"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["error_code"] = err_code or code
                r["error_message"] = msg
                r["updated_at"] = end_iso
                break
        _save("requests.json", requests)
        return _err(code, msg, http_status=http_status)

    # ---- validate inputs per business rules ----
    valid_sorting = {"date_added", "relevance", "random", "views", "favorites", "toplist"}
    valid_order = {"asc", "desc"}

    if not isinstance(sorting, str) or sorting not in valid_sorting:
        return _finalize_fail("VALIDATION_ERROR", "Invalid sorting", 400, err_code="INVALID_SORTING")
    if not isinstance(order, str) or order not in valid_order:
        return _finalize_fail("VALIDATION_ERROR", "Invalid order", 400, err_code="INVALID_ORDER")
    if not isinstance(page, int) or page < 1:
        return _finalize_fail("VALIDATION_ERROR", "page must be an integer >= 1", 400, err_code="INVALID_PAGE")

    # ---- ambient auth + rate/quota (authenticated request) ----
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _finalize_fail("UNAUTHORIZED", "No active API key available for this request", 401, err_code="NO_ACTIVE_KEY")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    one_min_ago = now - datetime.timedelta(minutes=1)
    last_min_counts = {}
    for r in requests:
        ak = r.get("api_key_id")
        if not ak:
            continue
        st = _parse_dt(r.get("started_at"))
        if st and st >= one_min_ago:
            last_min_counts[ak] = last_min_counts.get(ak, 0) + 1

    chosen = None
    quota_blocked = False
    rate_blocked = False
    for k in active_keys:
        kid = k.get("id")
        if not kid:
            continue

        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None:
            reset_at = now
        if reset_at.date() != now.date():
            k["requests_today"] = 0
            k["requests_today_reset_at"] = now_iso
            k["updated_at"] = now_iso

        daily_quota = k.get("daily_quota")
        rate_limit = k.get("rate_limit_per_minute")
        if not isinstance(daily_quota, int) or daily_quota < 1:
            continue
        if not isinstance(rate_limit, int) or rate_limit < 1:
            continue

        if int(k.get("requests_today") or 0) >= daily_quota:
            quota_blocked = True
            continue
        if last_min_counts.get(kid, 0) >= rate_limit:
            rate_blocked = True
            continue

        chosen = k
        break

    if chosen is None:
        _save("api_keys.json", api_keys)
        if quota_blocked:
            return _finalize_fail("QUOTA_EXCEEDED", "Daily quota exceeded", 429, err_code="DAILY_QUOTA_EXCEEDED")
        if rate_blocked:
            return _finalize_fail("RATE_LIMIT", "Rate limit exceeded", 429, err_code="RATE_LIMIT_EXCEEDED")
        return _finalize_fail("UNAUTHORIZED", "No eligible API key available", 401, err_code="NO_ELIGIBLE_KEY")

    # attach key to request row
    for r in requests:
        if r.get("id") == req_id:
            r["api_key_id"] = chosen["id"]
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    # increment daily usage counter
    chosen["requests_today"] = int(chosen.get("requests_today") or 0) + 1
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # ---- offline search over cached wallpapers ----
    wallpapers = _load("wallpapers.json")
    # only active wallpapers are searchable
    rows = [w for w in wallpapers if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("raw_payload"), dict)]

    # simple matching: query substring in various fields if query provided
    q = query.strip().lower() if isinstance(query, str) and query.strip() else None
    if q:
        def _hay(w):
            rp = w.get("raw_payload") or {}
            parts = []
            for k in ("id", "category", "purity", "resolution", "ratio", "source_url", "page_url", "file_url"):
                v = w.get(k) or rp.get(k)
                if isinstance(v, str):
                    parts.append(v.lower())
            # tags can be array of ints; include stringified
            tg = w.get("tags")
            if isinstance(tg, list):
                parts.append(" ".join(str(x) for x in tg))
            return " ".join(parts)
        rows = [w for w in rows if q in _hay(w)]

    total = len(rows)

    # sorting
    def _dt_key(w):
        s = w.get("fetched_at") or w.get("updated_at") or w.get("created_at")
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2) if isinstance(s2, str) else datetime.datetime(1970, 1, 1)
        except Exception:
            return datetime.datetime(1970, 1, 1)

    if sorting == "date_added":
        rows.sort(key=_dt_key, reverse=(order == "desc"))
    elif sorting in ("views", "favorites"):
        keyname = sorting
        rows.sort(key=lambda w: (w.get(keyname) if isinstance(w.get(keyname), int) else -1), reverse=(order == "desc"))
    elif sorting == "random":
        # deterministic shuffle by seed if provided, otherwise by request id
        import random as _random
        s = seed if isinstance(seed, str) and seed else req_id
        rng = _random.Random(s)
        rng.shuffle(rows)
    else:
        # relevance/toplist unsupported offline: keep stable order by id then apply order
        rows.sort(key=lambda w: w.get("id") or "")
        if order == "desc":
            rows.reverse()

    # pagination (Wallhaven defaults to 24 per page; we'll use 24)
    per_page = 24
    start = (page - 1) * per_page
    end = start + per_page
    page_items = rows[start:end]
    has_more = end < total

    data_items = []
    for w in page_items:
        data_items.append(w.get("raw_payload") or {})

    # mark cache hit (served from local cache only)
    for r in requests:
        if r.get("id") == req_id:
            r["upstream_cache_hit"] = True
            r["result_count"] = len(data_items)
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    return _finalize_ok(
        {
            "data": data_items,
            "meta": {
                "total": total,
                "per_page": per_page,
                "current_page": page,
                "last_page": (total + per_page - 1) // per_page if total else 0,
                "has_more": has_more,
            },
            "params": req_row["params"],
        },
        http_status=200,
        result_count=len(data_items),
        upstream_cache_hit=True,
    )

