    tag = None
    for row in tags:
        if isinstance(row, dict) and row.get("id") == tag_id:
            tag = row
            break

    if tag is None:
        return _finalize_fail("NOT_FOUND", "Tag not found", 404, err_code="TAG_NOT_FOUND")

    # mark cache hit
    for r in requests:
        if r.get("id") == req_id:
            r["upstream_cache_hit"] = True
            r["result_tag_id"] = tag_id
            r["result_count"] = 1
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    return _finalize_ok(
        {"data": tag.get("raw_payload") or {}},
        http_status=200,
        result_tag_id=tag_id,
        result_count=1,
        upstream_cache_hit=True,
    )

def get_user_settings(**_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- request log (received) ----
    requests = _load("requests.json")
    req_id = "req_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "api_key_id": None,
        "tool_name": "get_user_settings",
        "status": "received",
        "started_at": now_iso,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {},
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    requests.append(req_row)
    _save("requests.json", requests)

    def _finalize_ok(body, http_status=200, **updates):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "fulfilled"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["updated_at"] = end_iso
                for k, v in updates.items():
                    r[k] = v
                break
        _save("requests.json", requests)
        return body

    def _finalize_fail(code, msg, http_status, err_code=None):
        nonlocal requests, req_row
        end = datetime.datetime.utcnow().replace(microsecond=0)
        end_iso = end.isoformat() + "Z"
        for r in requests:
            if r.get("id") == req_row["id"]:
                if r.get("status") != "received":
                    break
                r["status"] = "failed"
                r["completed_at"] = end_iso
                r["http_status"] = http_status
                r["error_code"] = err_code or code
                r["error_message"] = msg
                r["updated_at"] = end_iso
                break
        _save("requests.json", requests)
        return _err(code, msg, http_status=http_status)

    # ---- authentication requirement (explicit in business rules) ----
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _finalize_fail("UNAUTHORIZED", "Missing or invalid API key", 401, err_code="MISSING_API_KEY")

    # Must be associated with a Wallhaven account via owner_user_id
    users = _load("users.json")
    user_by_id = {u.get("id"): u for u in users if isinstance(u, dict) and u.get("id")}

    # Also enforce rate/quota for authenticated request
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    one_min_ago = now - datetime.timedelta(minutes=1)
    last_min_counts = {}
    for r in requests:
        ak = r.get("api_key_id")
        if not ak:
            continue
        st = _parse_dt(r.get("started_at"))
        if st and st >= one_min_ago:
            last_min_counts[ak] = last_min_counts.get(ak, 0) + 1

    chosen = None
    quota_blocked = False
    rate_blocked = False
    for k in active_keys:
        kid = k.get("id")
        if not kid:
            continue

        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None:
            reset_at = now
        if reset_at.date() != now.date():
            k["requests_today"] = 0
            k["requests_today_reset_at"] = now_iso
            k["updated_at"] = now_iso

        daily_quota = k.get("daily_quota")
        rate_limit = k.get("rate_limit_per_minute")
        if not isinstance(daily_quota, int) or daily_quota < 1:
            continue
        if not isinstance(rate_limit, int) or rate_limit < 1:
            continue

        if int(k.get("requests_today") or 0) >= daily_quota:
            quota_blocked = True
            continue
        if last_min_counts.get(kid, 0) >= rate_limit:
            rate_blocked = True
            continue

        uid = k.get("owner_user_id")
        if not uid or uid not in user_by_id:
            continue
        if user_by_id[uid].get("status") != "active":
            continue

        chosen = k
        break

    if chosen is None:
        _save("api_keys.json", api_keys)
        if quota_blocked:
            return _finalize_fail("QUOTA_EXCEEDED", "Daily quota exceeded", 429, err_code="DAILY_QUOTA_EXCEEDED")
        if rate_blocked:
            return _finalize_fail("RATE_LIMIT", "Rate limit exceeded", 429, err_code="RATE_LIMIT_EXCEEDED")
        # differentiate 401 vs 403: if there is an active key but none linked to user => 401 per tool description
        any_linked = any(k.get("owner_user_id") in user_by_id for k in active_keys)
        if any_linked:
            return _finalize_fail("UNAUTHORIZED", "No eligible API key for user settings", 401, err_code="NO_ELIGIBLE_KEY")
        return _finalize_fail("UNAUTHORIZED", "API key not associated with a Wallhaven account", 401, err_code="KEY_NOT_LINKED")

    # attach key to request
    for r in requests:
        if r.get("id") == req_id:
            r["api_key_id"] = chosen["id"]
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    # increment daily usage counter
    chosen["requests_today"] = int(chosen.get("requests_today") or 0) + 1
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    user = user_by_id.get(chosen.get("owner_user_id"))
    if not user:
        return _finalize_fail("UNAUTHORIZED", "API key not associated with a Wallhaven account", 401, err_code="KEY_NOT_LINKED")

    settings = user.get("settings")
    # offline: must serve cached settings; if missing, treat as not found upstream? Vendor doesn't specify; return empty object.
    if settings is None:
        settings = {}

    # mark cache hit and result_user_id
    for r in requests:
        if r.get("id") == req_id:
            r["upstream_cache_hit"] = True
            r["result_user_id"] = user.get("id")
            r["result_count"] = 1
            r["updated_at"] = now_iso
            break
    _save("requests.json", requests)

    return _finalize_ok(
        {"data": settings},
        http_status=200,
        result_user_id=user.get("id"),
        result_count=1,
        upstream_cache_hit=True,
    )

def get_collection_wallpapers(username, collection_id, purity=None, page=1, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_collection_wallpapers"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _new_req_id():
        return "whv_req_" + uuid.uuid4().hex[:26]

    def _coerce_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _persist_rows(original_obj, filename, rows):
        if isinstance(original_obj, dict):
            original_obj["rows"] = rows
            _save(filename, original_obj)
        else:
            _save(filename, rows)

    def _day_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    # ---- Validate inputs (business rules)
    if not isinstance(username, str) or not username.strip():
        return _err("VALIDATION_ERROR", "username must be a non-empty string", http_status=400)
    username = username.strip()

    if not isinstance(collection_id, int) or collection_id < 1:
        return _err("VALIDATION_ERROR", "collection_id must be an integer >= 1", http_status=400)

    if purity is not None:
        if not isinstance(purity, str) or not purity.strip():
            return _err("VALIDATION_ERROR", "purity must be a non-empty string or null", http_status=400)
        purity = purity.strip().lower()
        # Do not over-restrict: accept any non-empty string (upstream supports combos)

    if page is None:
        page = 1
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", http_status=400)

    # ---- Load datastore
    api_keys_obj = _load("api_keys.json")
    api_keys = api_keys_obj if isinstance(api_keys_obj, list) else (api_keys_obj.get("rows") if isinstance(api_keys_obj, dict) else [])
    users_obj = _load("users.json")
    users = users_obj if isinstance(users_obj, list) else (users_obj.get("rows") if isinstance(users_obj, dict) else [])
    collections_obj = _load("collections.json")
    collections = collections_obj if isinstance(collections_obj, list) else (collections_obj.get("rows") if isinstance(collections_obj, dict) else [])
    wallpapers_obj = _load("wallpapers.json")
    wallpapers = wallpapers_obj if isinstance(wallpapers_obj, list) else (wallpapers_obj.get("rows") if isinstance(wallpapers_obj, dict) else [])
    requests_obj = _load("requests.json")
    request_rows = _coerce_rows(requests_obj)

    # ---- Ambient authentication for quota/observability
    # This endpoint must be logged and quota-enforced. There is no credential param, so pick a usable active key.
    # "Usable" here means: active and within rate/quota; if some active key can serve, do not UNAUTHORIZED.
    now = datetime.datetime.utcnow()
    started_at = _now_iso()
    req_id = _new_req_id()

    def _requests_in_last_minute_for_key(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            st = _parse_dt(r.get("started_at"))
            if st is None:
                continue
            if st >= cutoff:
                c += 1
        return c

    def _reset_daily_if_needed(k):
        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None:
            # If missing/invalid, treat as needing reset
            k["requests_today"] = 0
            k["requests_today_reset_at"] = _day_start_utc(now).isoformat() + "Z"
            return True
        # reset if key's recorded reset day is not today (UTC)
        if reset_at.date() != now.date():
            k["requests_today"] = 0
            k["requests_today_reset_at"] = _day_start_utc(now).isoformat() + "Z"
            return True
        return False

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id")]
    chosen_key = None
    for k in active_keys:
        # validate required fields for limits
        rl = k.get("rate_limit_per_minute")
        dq = k.get("daily_quota")
        rt = k.get("requests_today")
        if not isinstance(rl, int) or rl < 1:
            continue
        if not isinstance(dq, int) or dq < 1:
            continue
        if not isinstance(rt, int) or rt < 0:
            # normalize to 0
            k["requests_today"] = 0
        _reset_daily_if_needed(k)
        if k.get("requests_today", 0) >= dq:
            continue
        if _requests_in_last_minute_for_key(k["id"]) >= rl:
            continue
        chosen_key = k
        break

    # Create request log row as "received" (must always log)
    log_row = {
        "id": req_id,
        "api_key_id": chosen_key["id"] if chosen_key else (active_keys[0]["id"] if active_keys else None),
        "tool_name": tool_name,
        "status": "received",
        "started_at": started_at,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {
            "username": username,
            "collection_id": collection_id,
            "purity": purity,
            "page": page,
        },
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": True,
        "created_at": started_at,
        "updated_at": started_at,
    }
    request_rows.append(log_row)
    _persist_rows(requests_obj, "requests.json", request_rows)

    def _finalize_failed(code, message, http_status):
        completed = _now_iso()
        for r in request_rows:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["completed_at"] = completed
                r["http_status"] = http_status
                r["error_code"] = code
                r["error_message"] = message
                r["updated_at"] = completed
                break
        _persist_rows(requests_obj, "requests.json", request_rows)
        return _err(code, message, http_status=http_status)

    def _finalize_fulfilled(http_status, result_count, result_user_id=None, result_collection_id=None):
        completed = _now_iso()
        for r in request_rows:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "fulfilled"
                r["completed_at"] = completed
                r["http_status"] = http_status
                r["error_code"] = None
                r["error_message"] = None
                r["result_count"] = result_count
                if result_user_id is not None:
                    r["result_user_id"] = result_user_id
                if result_collection_id is not None:
                    r["result_collection_id"] = result_collection_id
                r["updated_at"] = completed
                break
        _persist_rows(requests_obj, "requests.json", request_rows)

    # ---- Enforce rate limit / daily quota for authenticated requests
    # If no active key can serve, return UNAUTHORIZED; if active keys exist but all exceed, return 429.
    if not active_keys:
        return _finalize_failed("UNAUTHORIZED", "No active API key available to serve request", 401)

    if chosen_key is None:
        # Determine whether it's rate limit or quota for a clearer error_code
        any_quota = False
        any_rate = False
        for k in active_keys:
            _reset_daily_if_needed(k)
            rl = k.get("rate_limit_per_minute")
            dq = k.get("daily_quota")
            if isinstance(dq, int) and k.get("requests_today", 0) >= dq:
                any_quota = True
            if isinstance(rl, int) and _requests_in_last_minute_for_key(k["id"]) >= rl:
                any_rate = True
        # Do not mutate cached entities; logging already done. Also avoid mutating counters on 429.
        if any_rate and not any_quota:
            return _finalize_failed("RATE_LIMIT", "Rate limit exceeded", 429)
        if any_quota:
            return _finalize_failed("QUOTA_EXCEEDED", "Daily quota exceeded", 429)
        return _finalize_failed("RATE_LIMIT", "Request cannot be served due to limits", 429)

    # Increment usage counters only after passing enforcement
    # This is a mutation, but allowed because the request is being served.
    chosen_key["requests_today"] = int(chosen_key.get("requests_today", 0)) + 1
    chosen_key["last_used_at"] = started_at
    chosen_key["updated_at"] = started_at
    _save("api_keys.json", api_keys_obj if isinstance(api_keys_obj, dict) else api_keys)

    # ---- Resolve user and collection
    user_row = None
    for u in users:
        if isinstance(u, dict) and u.get("username") == username and isinstance(u.get("id"), str):
            user_row = u
            break
    if user_row is None:
        return _finalize_failed("NOT_FOUND", "User not found", 404)

    # Join to collections on owner_user_id and upstream_collection_id
    matches = []
    for c in collections:
        if not isinstance(c, dict):
            continue
        if c.get("owner_user_id") != user_row.get("id"):
            continue
        if c.get("upstream_collection_id") != collection_id:
            continue
        matches.append(c)

    if len(matches) == 0:
        return _finalize_failed("NOT_FOUND", "Collection not found", 404)
    if len(matches) > 1:
        return _finalize_failed("CONFLICT", "Multiple collections matched username and collection_id", 409)

    col = matches[0]
    col_id = col.get("id")
    if not isinstance(col_id, str) or not col_id:
        return _finalize_failed("CONFLICT", "Collection row is missing id", 409)

    # If collection is deleted, treat as not found to callers (common upstream behavior)
    if col.get("status") == "deleted":
        return _finalize_failed("NOT_FOUND", "Collection not found", 404)

    # ---- Build page of wallpapers from cached ids
    wp_ids = col.get("wallpaper_ids")
    if not isinstance(wp_ids, list):
        wp_ids = []

    # Map for quick lookup
    wp_by_id = {}
    for w in wallpapers:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            wp_by_id[w["id"]] = w

    # Apply purity filter only when possible (if wallpaper has purity field)
    filtered_ids = []
    for wid in wp_ids:
        if not isinstance(wid, str):
            continue
        w = wp_by_id.get(wid)
        if w is None:
            continue
        if w.get("status") != "active":
            continue
        if purity is not None:
            wp_purity = w.get("purity")
            if isinstance(wp_purity, str):
                if wp_purity.lower() != purity:
                    continue
            else:
                # If purity unknown, conservatively exclude when filtering
                continue
        filtered_ids.append(wid)

    per_page = 24  # reasonable default page size for Wallhaven-style listing
    total = len(filtered_ids)
    last_page = max(1, (total + per_page - 1) // per_page)
    start = (page - 1) * per_page
    end = start + per_page

    # If the requested page is beyond last_page, return empty data with metadata (not an error)
    page_ids = filtered_ids[start:end] if start < total else []
    page_items = [wp_by_id[wid] for wid in page_ids if wid in wp_by_id]

    has_more = page < last_page
    next_cursor = str(page + 1) if has_more else None

    # Fulfill log
    _finalize_fulfilled(
        http_status=200,
        result_count=len(page_items),
        result_user_id=user_row.get("id"),
        result_collection_id=col_id,
    )

    return {
        "data": page_items,
        "meta": {
            "username": username,
            "collection_id": collection_id,
            "purity": purity,
            "page": page,
            "per_page": per_page,
            "total": total,
            "last_page": last_page,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "upstream_cache_hit": True,
        },
    }

def list_requests(api_key_id=None, status=None, tool_name=None, from_created_at=None, to_created_at=None, page=1, per_page=20, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")

    allowed_status = {"received", "fulfilled", "failed"}
    allowed_tools = {"get_wallpaper", "search_wallpapers", "get_tag_info", "get_user_settings", "get_collections", "get_collection_wallpapers"}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    # Validate filters
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string", http_status=400)
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status filter", http_status=400, allowed=sorted(allowed_status))
    if tool_name is not None and tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "Invalid tool_name filter", http_status=400, allowed=sorted(allowed_tools))
    if page is None:
        page = 1
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", http_status=400)
    if per_page is None:
        per_page = 20
    if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100", http_status=400)

    fdt = _parse_rfc3339(from_created_at)
    if from_created_at is not None and fdt is None:
        return _err("VALIDATION_ERROR", "from_created_at must be RFC3339 date-time", http_status=400)
    tdt = _parse_rfc3339(to_created_at)
    if to_created_at is not None and tdt is None:
        return _err("VALIDATION_ERROR", "to_created_at must be RFC3339 date-time", http_status=400)

    # Ambient authentication: require an active API key exists.
    auth_key = next((k for k in api_keys if k.get("status") == "active"), None)
    if auth_key is None:
        return _err("UNAUTHORIZED", "Missing/invalid/revoked API key", http_status=401)

    # Determine target key filter (defaults to authenticated key)
    target_key_id = api_key_id or auth_key.get("id")

    # FORBIDDEN when requesting another key’s logs without ownership:
    # Ownership model isn't present; implement strict: only allow own key id.
    if target_key_id != auth_key.get("id"):
        return _err("UNAUTHORIZED", "Cannot access another API key's logs", http_status=403)

    # Filter
    filtered = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != target_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        cd = _parse_rfc3339(r.get("created_at"))
        if fdt is not None and (cd is None or cd < fdt):
            continue
        if tdt is not None and (cd is None or cd > tdt):
            continue
        filtered.append(r)

    # Sort created_at desc (fallback to started_at)
    def _sort_key(r):
        cd = _parse_rfc3339(r.get("created_at")) or _parse_rfc3339(r.get("started_at")) or datetime.datetime(1970, 1, 1)
        return cd
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    start = (page - 1) * per_page
    end = start + per_page
    items = filtered[start:end] if start < total else []
    has_more = end < total

    return {
        "data": items,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "has_more": has_more
        }
    }

def get_request(request_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "get_request"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _new_req_id():
        return "whv_req_" + uuid.uuid4().hex[:26]

    def _coerce_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _persist_rows(original_obj, filename, rows):
        if isinstance(original_obj, dict):
            original_obj["rows"] = rows
            _save(filename, original_obj)
        else:
            _save(filename, rows)

    # Validate
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string", http_status=400)
    request_id = request_id.strip()

    api_keys_obj = _load("api_keys.json")
    api_keys = api_keys_obj if isinstance(api_keys_obj, list) else (api_keys_obj.get("rows") if isinstance(api_keys_obj, dict) else [])
    requests_obj = _load("requests.json")
    request_rows = _coerce_rows(requests_obj)

    now = datetime.datetime.utcnow()
    started_at = _now_iso()
    log_id = _new_req_id()

    # Ambient authentication (tool has no credential param):
    # pick an active key that is within limits, otherwise return 429; only UNAUTHORIZED if none active exist.
    def _requests_in_last_minute_for_key(key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in request_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            st = _parse_dt(r.get("started_at"))
            if st is None:
                continue
            if st >= cutoff:
                c += 1
        return c

    def _day_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    def _reset_daily_if_needed(k):
        reset_at = _parse_dt(k.get("requests_today_reset_at"))
        if reset_at is None or reset_at.date() != now.date():
            k["requests_today"] = 0
            k["requests_today_reset_at"] = _day_start_utc(now).isoformat() + "Z"
            return True
        return False

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id")]
    chosen_key = None
    for k in active_keys:
        rl = k.get("rate_limit_per_minute")
        dq = k.get("daily_quota")
        if not isinstance(rl, int) or rl < 1:
            continue
        if not isinstance(dq, int) or dq < 1:
            continue
        _reset_daily_if_needed(k)
        if int(k.get("requests_today", 0) or 0) >= dq:
            continue
        if _requests_in_last_minute_for_key(k["id"]) >= rl:
            continue
        chosen_key = k
        break

    # Log this tool invocation itself (observability)
    log_row = {
        "id": log_id,
        "api_key_id": chosen_key["id"] if chosen_key else (active_keys[0]["id"] if active_keys else None),
        "tool_name": tool_name,
        "status": "received",
        "started_at": started_at,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {"request_id": request_id},
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": True,
        "created_at": started_at,
        "updated_at": started_at,
    }
    request_rows.append(log_row)
    _persist_rows(requests_obj, "requests.json", request_rows)

    def _finalize_failed(code, message, http_status):
        completed = _now_iso()
        for r in request_rows:
            if isinstance(r, dict) and r.get("id") == log_id:
                r["status"] = "failed"
                r["completed_at"] = completed
                r["http_status"] = http_status
                r["error_code"] = code
                r["error_message"] = message
                r["updated_at"] = completed
                break
        _persist_rows(requests_obj, "requests.json", request_rows)
        return _err(code, message, http_status=http_status)

    def _finalize_fulfilled(http_status, result_count=1):
        completed = _now_iso()
        for r in request_rows:
            if isinstance(r, dict) and r.get("id") == log_id:
                r["status"] = "fulfilled"
                r["completed_at"] = completed
                r["http_status"] = http_status
                r["error_code"] = None
                r["error_message"] = None
                r["result_count"] = result_count
                r["updated_at"] = completed
                break
        _persist_rows(requests_obj, "requests.json", request_rows)

    # Enforce limits / auth presence
    if not active_keys:
        return _finalize_failed("UNAUTHORIZED", "No active API key available", 401)
    if chosen_key is None:
        any_quota = False
        any_rate = False
        for k in active_keys:
            _reset_daily_if_needed(k)
            rl = k.get("rate_limit_per_minute")
            dq = k.get("daily_quota")
            if isinstance(dq, int) and int(k.get("requests_today", 0) or 0) >= dq:
                any_quota = True
            if isinstance(rl, int) and _requests_in_last_minute_for_key(k["id"]) >= rl:
                any_rate = True
        if any_rate and not any_quota:
            return _finalize_failed("RATE_LIMIT", "Rate limit exceeded", 429)
        if any_quota:
            return _finalize_failed("QUOTA_EXCEEDED", "Daily quota exceeded", 429)
        return _finalize_failed("RATE_LIMIT", "Request cannot be served due to limits", 429)

    # Apply usage counters now that request is allowed
    chosen_key["requests_today"] = int(chosen_key.get("requests_today", 0) or 0) + 1
    chosen_key["last_used_at"] = started_at
    chosen_key["updated_at"] = started_at
    _save("api_keys.json", api_keys_obj if isinstance(api_keys_obj, dict) else api_keys)

    # Fetch the referenced request row
    target = None
    for r in request_rows:
        if isinstance(r, dict) and r.get("id") == request_id:
            target = r
            break

    if target is None:
        return _finalize_failed("NOT_FOUND", "Request not found", 404)

    # Authorization: request must belong to authenticated key (FORBIDDEN otherwise)
    # (Allow if request.api_key_id is None? treat as forbidden because it doesn't belong)
    if target.get("api_key_id") != chosen_key.get("id"):
        return _finalize_failed("UNAUTHORIZED" if target.get("api_key_id") is None else "UNAUTHORIZED", "Not authorized to access this request", 403)

    _finalize_fulfilled(200, result_count=1)
    return {"data": target}

def create_api_key(label, rate_limit_per_minute=None, daily_quota=None, **_extra):
    import json, os, datetime, secrets, hashlib, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
