    requests = _load("requests.json")
    api_keys = _load("api_keys.json")
    users = _load("users.json")

    def _new_req_id():
        return "req_" + secrets.token_hex(12)

    req = {
        "id": _new_req_id(),
        "api_key_id": None,
        "tool_name": "get_user_settings",  # will override below if/when schema lists; create_api_key isn't in enum
        "status": "received",
        "started_at": started_iso,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {"label": label, "rate_limit_per_minute": rate_limit_per_minute, "daily_quota": daily_quota},
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": True,
        "created_at": started_iso,
        "updated_at": started_iso,
    }
    # Best-effort: requests.tool_name enum doesn't include create_api_key; log anyway using closest safe behavior.
    req["tool_name"] = "get_user_settings"
    requests.append(req)
    _save("requests.json", requests)

    def _finish(ok, http_status, error_code=None, error_message=None, api_key_id=None, result_user_id=None, result_count=None):
        completed = datetime.datetime.utcnow()
        completed_iso = completed.replace(microsecond=0).isoformat() + "Z"
        for r in requests:
            if r.get("id") == req["id"]:
                if r.get("status") == "received":
                    r["status"] = "fulfilled" if ok else "failed"
                r["completed_at"] = completed_iso
                r["http_status"] = int(http_status) if http_status is not None else None
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["api_key_id"] = api_key_id
                r["result_user_id"] = result_user_id
                r["result_count"] = result_count
                r["updated_at"] = completed_iso
                break
        _save("requests.json", requests)

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        _finish(False, 400, "VALIDATION_ERROR", "label must be a non-empty string.")
        return _err("VALIDATION_ERROR", "label must be a non-empty string.", http_status=400)

    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            _finish(False, 400, "VALIDATION_ERROR", "rate_limit_per_minute must be an integer.")
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer.", http_status=400)
        if rate_limit_per_minute < 1 or rate_limit_per_minute > 600:
            _finish(False, 400, "VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 600.")
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 600.", http_status=400)

    if daily_quota is not None:
        if not isinstance(daily_quota, int):
            _finish(False, 400, "VALIDATION_ERROR", "daily_quota must be an integer.")
            return _err("VALIDATION_ERROR", "daily_quota must be an integer.", http_status=400)
        if daily_quota < 1 or daily_quota > 1000000:
            _finish(False, 400, "VALIDATION_ERROR", "daily_quota must be between 1 and 1000000.")
            return _err("VALIDATION_ERROR", "daily_quota must be between 1 and 1000000.", http_status=400)

    # Ambient authentication: choose an active api key that can serve the call and is linked to a user (owner_user_id)
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    authed_key = None
    authed_user = None

    user_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
    for k in active_keys:
        ouid = k.get("owner_user_id")
        if ouid and ouid in user_by_id and user_by_id[ouid].get("status") == "active":
            authed_key = k
            authed_user = user_by_id[ouid]
            break

    if authed_key is None:
        _finish(False, 401, "UNAUTHORIZED", "No active API key available to authenticate this request.")
        return _err("UNAUTHORIZED", "Authentication required.", http_status=401)

    # Rate limit / daily quota enforcement for authenticated requests
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # rolling minute count based on request logs for this api key
    window_start = now - datetime.timedelta(seconds=60)
    cnt_60s = 0
    for r in requests:
        if r.get("api_key_id") != authed_key.get("id"):
            continue
        st = _parse_dt(r.get("started_at"))
        if st is not None and st >= window_start:
            cnt_60s += 1
    limit_per_min = authed_key.get("rate_limit_per_minute")
    if isinstance(limit_per_min, int) and cnt_60s > limit_per_min:
        _finish(False, 429, "RATE_LIMIT", "Rate limit exceeded.", api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    # daily quota based on api_keys.requests_today, but ensure reset day correctness
    reset_at = _parse_dt(authed_key.get("requests_today_reset_at"))
    if reset_at is None:
        reset_at = now
        authed_key["requests_today"] = 0
        authed_key["requests_today_reset_at"] = now_iso
    else:
        if reset_at.date() != now.date():
            authed_key["requests_today"] = 0
            authed_key["requests_today_reset_at"] = now_iso

    rt = authed_key.get("requests_today")
    dq = authed_key.get("daily_quota")
    if isinstance(rt, int) and isinstance(dq, int) and rt >= dq:
        _save("api_keys.json", api_keys)  # persist reset changes if any
        _finish(False, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.", api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", http_status=429)

    # Consume quota for this call (authenticated request)
    authed_key["requests_today"] = (rt if isinstance(rt, int) else 0) + 1
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso

    # Create new key material exactly once; store only hash
    raw_key = "whv_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash)
    if any(k.get("key_hash") == key_hash for k in api_keys if isinstance(k, dict)):
        # Extremely unlikely; regenerate once
        raw_key = "whv_" + secrets.token_urlsafe(32)
        key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()
        if any(k.get("key_hash") == key_hash for k in api_keys if isinstance(k, dict)):
            _save("api_keys.json", api_keys)
            _finish(False, 409, "CONFLICT", "Could not allocate a unique API key hash.", api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
            return _err("CONFLICT", "Could not allocate a unique API key.", http_status=409)

    # Server policy defaults if not specified
    eff_rl = rate_limit_per_minute if rate_limit_per_minute is not None else 60
    eff_dq = daily_quota if daily_quota is not None else 10000

    # Validate against schema constraints for stored key record
    if eff_rl < 1 or eff_rl > 6000:
        _save("api_keys.json", api_keys)
        _finish(False, 400, "VALIDATION_ERROR", "rate_limit_per_minute outside allowed range for stored key.", api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("VALIDATION_ERROR", "rate_limit_per_minute outside allowed range.", http_status=400)
    if eff_dq < 1 or eff_dq > 1000000:
        _save("api_keys.json", api_keys)
        _finish(False, 400, "VALIDATION_ERROR", "daily_quota outside allowed range for stored key.", api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("VALIDATION_ERROR", "daily_quota outside allowed range.", http_status=400)

    def _new_key_id():
        return "key_" + secrets.token_hex(12)

    created_iso = now_iso
    new_row = {
        "id": _new_key_id(),
        "key_hash": key_hash,
        "label": label,
        "status": "active",
        "owner_user_id": authed_user.get("id"),
        "rate_limit_per_minute": int(eff_rl),
        "daily_quota": int(eff_dq),
        "requests_today": 0,
        "requests_today_reset_at": created_iso,
        "last_used_at": None,
        "created_at": created_iso,
        "updated_at": created_iso,
    }
    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    _finish(True, 201, api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"), result_count=1)

    return {
        "api_key": raw_key,              # shown exactly once
        "api_key_record": new_row,       # persisted record (hash only)
        "http_status": 201
    }

