        return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    reset_at = _parse_dt(authed_key.get("requests_today_reset_at"))
    if reset_at is None or reset_at.date() != now.date():
        authed_key["requests_today"] = 0
        authed_key["requests_today_reset_at"] = now_iso
    rt = authed_key.get("requests_today")
    dq = authed_key.get("daily_quota")
    if isinstance(rt, int) and isinstance(dq, int) and rt >= dq:
        _save("api_keys.json", api_keys)
        _finish(False, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", http_status=429)

    # Consume quota for this call
    authed_key["requests_today"] = (rt if isinstance(rt, int) else 0) + 1
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso

    # Find the target key
    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            target = k
            break
    if target is None:
        _save("api_keys.json", api_keys)
        _finish(False, 404, "NOT_FOUND", "API key not found.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("NOT_FOUND", "API key not found.", http_status=404)

    # Ownership enforcement
    if target.get("owner_user_id") != authed_user.get("id"):
        _save("api_keys.json", api_keys)
        _finish(False, 403, "UNAUTHORIZED", "Not permitted to update API key not owned by caller.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("UNAUTHORIZED", "Forbidden.", http_status=403)

    # Apply updates with lifecycle validation
    changed = False
    if label is not None and label != target.get("label"):
        target["label"] = label
        changed = True

    if status is not None and status != target.get("status"):
        cur = target.get("status")
        if cur == "active" and status == "revoked":
            target["status"] = "revoked"
            changed = True
        elif cur == "revoked":
            _save("api_keys.json", api_keys)
            _finish(False, 400, "INVALID_TRANSITION", "revoked is terminal; cannot transition.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
            return _err("INVALID_TRANSITION", "Illegal status transition.", http_status=400)
        elif cur == "active" and status == "active":
            pass
        else:
            _save("api_keys.json", api_keys)
            _finish(False, 400, "INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
            return _err("INVALID_TRANSITION", "Illegal status transition.", http_status=400)

    if not changed:
        # No success without effect for mutations
        _save("api_keys.json", api_keys)
        _finish(False, 409, "CONFLICT", "No changes to apply.", authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"))
        return _err("CONFLICT", "No changes to apply.", http_status=409)

    target["updated_at"] = now_iso
    _save("api_keys.json", api_keys)
    _finish(True, 200, authed_api_key_id=authed_key.get("id"), result_user_id=authed_user.get("id"), result_count=1)

    return {"api_key_record": target, "http_status": 200}

def update_wallpaper_status(wallpaper_id, status, **_extra):
    import json, os, datetime, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0483000" if __import__("os").path.isdir("./environment_mix/0483000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "update_wallpaper_status"
    started_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(wallpaper_id, str) or re.fullmatch(r"^[0-9a-z]{6}$", wallpaper_id) is None:
        return _err("VALIDATION_ERROR", "wallpaper_id must match ^[0-9a-z]{6}$", http_status=400)
    if not isinstance(status, str) or status not in ("active", "blocked", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of {active, blocked, deleted}", http_status=400)

    api_keys = _load("api_keys.json")
    wallpapers = _load("wallpapers.json")
    requests = _load("requests.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _new_req_id():
        return "whv_req_" + uuid.uuid4().hex[:26]

    # Authenticate: since no explicit credential parameter exists, use ambient context:
    # pick an active key that can serve the request (status=active).
    auth_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if auth_key is None:
        # Still log the request as failed for observability
        rid = _new_req_id()
        nowi = _now_iso()
        requests.append({
            "id": rid,
            "api_key_id": None,
            "tool_name": "get_wallpaper",  # closest enum tool
            "status": "failed",
            "started_at": started_iso,
            "completed_at": nowi,
            "http_status": 401,
            "error_code": "UNAUTHORIZED",
            "error_message": "Missing/invalid/revoked API key.",
            "params": {"wallpaper_id": wallpaper_id, "status": status},
            "result_wallpaper_id": None,
            "result_tag_id": None,
            "result_user_id": None,
            "result_collection_id": None,
            "result_count": None,
            "upstream_cache_hit": True,
            "created_at": nowi,
            "updated_at": nowi,
        })
        _save("requests.json", requests)
        return _err("UNAUTHORIZED", "Missing/invalid/revoked API key", http_status=401)

    auth_key_id = auth_key.get("id")

    # Log received
    req_id = _new_req_id()
    nowi = _now_iso()
    requests.append({
        "id": req_id,
        "api_key_id": auth_key_id,
        "tool_name": "get_wallpaper",  # closest enum match
        "status": "received",
        "started_at": started_iso,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "params": {"wallpaper_id": wallpaper_id, "status": status},
        "result_wallpaper_id": None,
        "result_tag_id": None,
        "result_user_id": None,
        "result_collection_id": None,
        "result_count": None,
        "upstream_cache_hit": True,
        "created_at": nowi,
        "updated_at": nowi,
    })
    _save("requests.json", requests)

    def _finalize(ok, http_status, error_code=None, error_message=None, result_wallpaper_id=None):
        completed_iso = _now_iso()
        for r in requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                if r.get("status") == "received":
                    r["status"] = "fulfilled" if ok else "failed"
                r["completed_at"] = completed_iso
                r["http_status"] = int(http_status)
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["result_wallpaper_id"] = result_wallpaper_id
                r["updated_at"] = completed_iso
                break
        _save("requests.json", requests)

    # Enforce quota + rate limit (do not mutate cached entities on 429)
    reset_at = _parse_dt(auth_key.get("requests_today_reset_at"))
    utc_today = datetime.datetime.utcnow().date()
    key_mutated = False
    if reset_at is None or reset_at.date() != utc_today:
        auth_key["requests_today"] = 0
        auth_key["requests_today_reset_at"] = _now_iso()
        key_mutated = True

    daily_quota = auth_key.get("daily_quota")
    requests_today = auth_key.get("requests_today", 0)
    if not isinstance(daily_quota, int) or daily_quota < 1:
        _finalize(False, 401, "UNAUTHORIZED", "API key is misconfigured (daily_quota).")
        return _err("UNAUTHORIZED", "Missing/invalid/revoked API key", http_status=401)
    if not isinstance(requests_today, int) or requests_today < 0:
        requests_today = 0
        auth_key["requests_today"] = 0
        key_mutated = True
    if requests_today >= daily_quota:
        _finalize(False, 429, "QUOTA_EXCEEDED", "Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", http_status=429)

    rpm = auth_key.get("rate_limit_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        _finalize(False, 401, "UNAUTHORIZED", "API key is misconfigured (rate_limit_per_minute).")
        return _err("UNAUTHORIZED", "Missing/invalid/revoked API key", http_status=401)

    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    cnt = 0
    for rr in requests:
        if not isinstance(rr, dict):
            continue
        if rr.get("api_key_id") != auth_key_id:
            continue
        st = _parse_dt(rr.get("started_at"))
        if st is not None and st >= cutoff:
            cnt += 1
    if cnt > rpm:
        _finalize(False, 429, "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded", http_status=429)

    # Find wallpaper
    idx = None
    wp = None
    for i, w in enumerate(wallpapers):
        if isinstance(w, dict) and w.get("id") == wallpaper_id:
            idx = i
            wp = w
            break
    if wp is None:
        _finalize(False, 404, "NOT_FOUND", "Wallpaper not found.")
        return _err("NOT_FOUND", "Wallpaper not found", http_status=404)

    # Enforce lifecycle transitions
    cur = wp.get("status")
    allowed = {
        "active": {"blocked", "deleted"},
        "blocked": {"active"},
        "deleted": set(),
    }
    if cur not in allowed:
        _finalize(False, 409, "CONFLICT", "Wallpaper has unknown lifecycle status.")
        return _err("CONFLICT", "Wallpaper has unknown lifecycle status", http_status=409)

    if status == cur:
        # Idempotent: still counts as a fulfilled request, but no entity mutation.
        # Count request against quota (all authenticated calls)
        auth_key["requests_today"] = int(requests_today) + 1
        auth_key["last_used_at"] = _now_iso()
        auth_key["updated_at"] = _now_iso()
        key_mutated = True
        if key_mutated:
            for j, k in enumerate(api_keys):
                if isinstance(k, dict) and k.get("id") == auth_key_id:
                    api_keys[j] = auth_key
                    break
            _save("api_keys.json", api_keys)

        _finalize(True, 200, result_wallpaper_id=wallpaper_id)
        return {"data": wp}

    if status not in allowed[cur]:
        _finalize(False, 409, "INVALID_TRANSITION", f"Illegal wallpaper status transition {cur} -> {status}.")
        return _err("INVALID_TRANSITION", f"Illegal wallpaper status transition {cur} -> {status}", http_status=409)

    # Apply mutation
    nowu = _now_iso()
    wp["status"] = status
    wp["updated_at"] = nowu
    wallpapers[idx] = wp
    _save("wallpapers.json", wallpapers)

    # Count request against quota (all authenticated calls)
    auth_key["requests_today"] = int(requests_today) + 1
    auth_key["last_used_at"] = nowu
    auth_key["updated_at"] = nowu
    for j, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == auth_key_id:
            api_keys[j] = auth_key
            break
    _save("api_keys.json", api_keys)

    _finalize(True, 200, result_wallpaper_id=wallpaper_id)
    return {"data": wp}
